import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTALS ----------
    rev_tw_total = df['Revenue_TW'].dropna().sum() if df['Revenue_TW'].notna().any() else None
    rev_lw_total = df['Revenue_LW'].dropna().sum() if df['Revenue_LW'].notna().any() else None
    rev_ly_total = df['Revenue_LY'].dropna().sum() if df['Revenue_LY'].notna().any() else None
    units_tw_total = df['Units_TW'].dropna().sum() if df['Units_TW'].notna().any() else None
    units_lw_total = df['Units_LW'].dropna().sum() if df['Units_LW'].notna().any() else None
    orders_tw_total = df['Orders_TW'].dropna().sum() if df['Orders_TW'].notna().any() else None
    orders_lw_total = df['Orders_LW'].dropna().sum() if df['Orders_LW'].notna().any() else None

    if rev_tw_total is not None:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "TW",
            "value": round(float(rev_tw_total), 2),
            "formula": "sum(Revenue_TW) across all entities"
        })
    if rev_lw_total is not None:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LW",
            "value": round(float(rev_lw_total), 2),
            "formula": "sum(Revenue_LW) across all entities"
        })
    if rev_ly_total is not None:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(rev_ly_total), 2),
            "formula": "sum(Revenue_LY) across all entities"
        })
    if units_tw_total is not None:
        facts.append({
            "entity": "TOTAL", "metric": "units", "period": "TW",
            "value": round(float(units_tw_total), 2),
            "formula": "sum(Units_TW) across all entities"
        })
    if units_lw_total is not None:
        facts.append({
            "entity": "TOTAL", "metric": "units", "period": "LW",
            "value": round(float(units_lw_total), 2),
            "formula": "sum(Units_LW) across all entities"
        })
    if orders_tw_total is not None:
        facts.append({
            "entity": "TOTAL", "metric": "orders", "period": "TW",
            "value": round(float(orders_tw_total), 2),
            "formula": "sum(Orders_TW) across all entities"
        })
    if orders_lw_total is not None:
        facts.append({
            "entity": "TOTAL", "metric": "orders", "period": "LW",
            "value": round(float(orders_lw_total), 2),
            "formula": "sum(Orders_LW) across all entities"
        })

    # Total WoW pct
    if rev_tw_total is not None and rev_lw_total is not None and rev_lw_total != 0:
        wow_total = (rev_tw_total - rev_lw_total) / rev_lw_total * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(wow_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    # Total YoY pct
    if rev_tw_total is not None and rev_ly_total is not None and rev_ly_total != 0:
        yoy_total = (rev_tw_total - rev_ly_total) / rev_ly_total * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(yoy_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---------- TOP 5 ENTITIES BY REVENUE_TW ----------
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "TW",
            "value": round(float(row['Revenue_TW']), 2),
            "formula": "Revenue_TW for entity"
        })

    # ---------- TOP 3 WoW GAINERS ----------
    wow_sorted = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=False)
    top_wow_gain = wow_sorted.head(3)
    for _, row in top_wow_gain.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "WoW",
            "value": round(float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---------- TOP 3 WoW DECLINERS ----------
    top_wow_decline = wow_sorted.tail(3).sort_values('WoW_Pct', ascending=True)
    for _, row in top_wow_decline.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "WoW",
            "value": round(float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---------- TOP 3 YoY GAINERS ----------
    yoy_sorted = df.dropna(subset=['YoY_Pct']).sort_values('YoY_Pct', ascending=False)
    top_yoy_gain = yoy_sorted.head(3)
    for _, row in top_yoy_gain.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "YoY",
            "value": round(float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # ---------- TOP 2 YoY DECLINERS ----------
    top_yoy_decline = yoy_sorted.tail(2).sort_values('YoY_Pct', ascending=True)
    for _, row in top_yoy_decline.iterrows():
        facts.append({
            "entity": str(row['Entity']),
            "metric": "revenue",
            "period": "YoY",
            "value": round(float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Limit to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
